// THE FENCE BATTERY - the fold must prove itself (the fence law: the
// word never rides a lie); extra keys never rejected (the fence never
// invents exclusions)
assert.equal(tunnelSealedTrendRow(null), null, 'the null fold the fence refuses')
assert.equal(tunnelSealedTrendRow(undefined), null, 'the undefined fold the fence refuses')
assert.equal(tunnelSealedTrendRow('junk'), null, 'the junk fold the fence refuses')
assert.equal(tunnelSealedTrendRow([]), null, 'the array fold the fence refuses')
assert.equal(tunnelSealedTrendRow({}), null, 'the empty fold the fence refuses')
assert.equal(tunnelSealedTrendRow({ back: { tunnelSealeds: 1 }, prev: { tunnelSealeds: 2 } }), null, 'the missing face the fence refuses')
assert.equal(tunnelSealedTrendRow({ back: { tunnelSealeds: 1 }, prev: { tunnelSealeds: 2 }, cur: { tunnelSealeds: 1.5 } }), null, 'the non-integer the fence refuses')
assert.equal(tunnelSealedTrendRow({ back: { tunnelSealeds: 1 }, prev: { tunnelSealeds: 2 }, cur: { tunnelSealeds: -1 } }), null, 'the negative the fence refuses')
assert.equal(tunnelSealedTrendRow({ back: { tunnelSealeds: '1' }, prev: { tunnelSealeds: 2 }, cur: { tunnelSealeds: 3 } }), null, 'the string count the fence refuses')
assert.equal(tunnelSealedTrendConsistent({ back: { tunnelSealeds: 0 }, prev: { tunnelSealeds: 0 }, cur: { tunnelSealeds: 0 } }), true, 'the zero fold rides - the honest drought\'s own zero the lawful count')
assert.equal(tunnelSealedTrendRow({ back: { tunnelSealeds: 4, extra: 'x' }, prev: { tunnelSealeds: 4, extra: 'y' }, cur: { tunnelSealeds: 9, extra: 'z' } }), null, 'the held fold prices no direction - the honest silence the row never invents')
assert.equal(tunnelSealedTrendRow({ back: { tunnelSealeds: 0, extra: 'x' }, prev: { tunnelSealeds: 5, extra: 'y' }, cur: { tunnelSealeds: 9, extra: 'z' } }), SWELL + '0 -> 5 (+5) -> 9 (+4)' + SWELL_TAIL, 'the extra keys never rejected - the fence never invents exclusions')

// THE BYTE-PIN BATTERY - the row never speaks the shape's own verdict
// words nor the seats' own verdict word nor the dynasty's own
// (co-existence by seat never by duplication)
const voices = [
  tunnelSealedTrendRow({ back: { tunnelSealeds: 1 }, prev: { tunnelSealeds: 2 }, cur: { tunnelSealeds: 3 } }),
  tunnelSealedTrendRow({ back: { tunnelSealeds: 3 }, prev: { tunnelSealeds: 2 }, cur: { tunnelSealeds: 1 } }),
  tunnelSealedTrendRow({ back: { tunnelSealeds: 1 }, prev: { tunnelSealeds: 3 }, cur: { tunnelSealeds: 2 } }),
]
for (const banned of ['return', 'repeat', 'stay', 'run', 'owns', 'dynasty', 'turn']) {
  for (const v of voices) {
    assert.equal(v.includes(banned), false, `the byte-pin holds - the ${banned} word never rides the row`)
  }
}
for (const v of voices) {
  assert.equal(v.endsWith('co-existence by seat never by duplication)'), true, 'the tail\'s own close the byte rides')
  assert.equal(v.includes("the fuel commons' own dry grain trend prices the fuel commons' own dry grain mass across the faces"), true, 'the newest sibling the tail names - the grain lane beside')
  assert.equal(v.includes("this word prices the tunnel's own sealed-or-flooded mass across the faces - the tunnel sealed seat"), true, 'the word\'s own naming the tail holds')
}

